window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c8dc67bef9ec885b"]={"versions": [{"id": "FIG-c8dc67bef9ec885b", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition von ungültigen Statuswert-Kombinationen (Invalid combination of status values) im Rahmen des AUTOSAR Generic Structure Template (M2-Metamodell). Es visualisiert die semantischen Gültigkeitsbereiche für Status-Tags (<code>atp.Status</code>) bei hierarchischen Aggregationen und Referenzen zwischen Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>parent: ClassA</code>: Metaklasse als Aggregationsursprung mit Tag <code>atp.Status = obsolete</code>.\n</li><li><code>child: ClassB</code>: Aggregierte Metaklasse mit Tag <code>atp:Status = obsolete</code>.\n</li><li>Aggregationsbeziehung (<code>aggregation</code>): Komposition von <code>parent: ClassA</code> zu <code>child: ClassB</code> mit Notiz <code>aggregation Tags: atp.Status = valid</code>.\n</li><li><code>source: ClassA</code>: Metaklasse als Referenzursprung mit Tag <code>atp.Status = obsolete</code>.\n</li><li><code>target: ClassB</code>: Referenzierte Metaklasse mit Tag <code>atp.Status = obsolete</code>.\n</li><li>Referenzbeziehung (<code>reference</code>): Gerichtete Assoziation von <code>source: ClassA</code> zu <code>target: ClassB</code> mit Notiz <code>reference Tags: atp.Status = valid</code>.\n</li><li>Blauer gestrichelter Rahmen: Definiert den Gültigkeitsbereich <code>Scope of table status value combinations with parent/source Class</code>, der die Quellklassen (<code>parent: ClassA</code>, <code>source: ClassA</code>) sowie die Beziehungsnotizen umschließt.\n</li><li>Hellblauer (türkiser) gestrichelter Rahmen: Definiert den Gültigkeitsbereich <code>Scope of table status value combinations with child/target Class</code>, der die Zielklassen (<code>child: ClassB</code>, <code>target: ClassB</code>) sowie die Beziehungsnotizen umschließt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell-Regeldiagramm ohne dynamische Ablauf- oder Nachrichtensequenzen. Es stellt die Überlappung der Prüfbereiche (Scopes) für Status-Kombinationen dar: Die Beziehungsattribute/Tags (<code>aggregation Tags</code>, <code>reference Tags</code>) liegen im Schnittbereich der Tabellenprüfungen für Quell- und Zielelemente.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm demonstriert eine unzulässige Statuskombination: Wenn sowohl Quell-/Elternelement (<code>ClassA</code>) als auch Ziel-/Kindelement (<code>ClassB</code>) als <code>obsolete</code> deklariert sind, darf die verbindende Aggregation bzw. Referenz nicht den Status <code>valid</code> tragen. Metamodell-Validierungswerkzeuge müssen sicherstellen, dass Beziehungen zwischen obsoleten Klassen nicht als vollgültig (<code>valid</code>) eingestuft werden.</p>"}, {"id": "FIG-04cb6c1357ca9082", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition von ungültigen Statuswert-Kombinationen (Invalid combination of status values) im Rahmen des AUTOSAR Generic Structure Template (M2-Metamodell). Es visualisiert die semantischen Gültigkeitsbereiche für Status-Tags (<code>atp.Status</code>) bei hierarchischen Aggregationen und Referenzen zwischen Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>parent: ClassA</code>: Metaklasse als Aggregationsursprung mit Tag <code>atp.Status = obsolete</code>.\n</li><li><code>child: ClassB</code>: Aggregierte Metaklasse mit Tag <code>atp:Status = obsolete</code>.\n</li><li>Aggregationsbeziehung (<code>aggregation</code>): Komposition von <code>parent: ClassA</code> zu <code>child: ClassB</code> mit Notiz <code>aggregation Tags: atp.Status = valid</code>.\n</li><li><code>source: ClassA</code>: Metaklasse als Referenzursprung mit Tag <code>atp.Status = obsolete</code>.\n</li><li><code>target: ClassB</code>: Referenzierte Metaklasse mit Tag <code>atp.Status = obsolete</code>.\n</li><li>Referenzbeziehung (<code>reference</code>): Gerichtete Assoziation von <code>source: ClassA</code> zu <code>target: ClassB</code> mit Notiz <code>reference Tags: atp.Status = valid</code>.\n</li><li>Blauer gestrichelter Rahmen: Definiert den Gültigkeitsbereich <code>Scope of table status value combinations with parent/source Class</code>, der die Quellklassen (<code>parent: ClassA</code>, <code>source: ClassA</code>) sowie die Beziehungsnotizen umschließt.\n</li><li>Hellblauer (türkiser) gestrichelter Rahmen: Definiert den Gültigkeitsbereich <code>Scope of table status value combinations with child/target Class</code>, der die Zielklassen (<code>child: ClassB</code>, <code>target: ClassB</code>) sowie die Beziehungsnotizen umschließt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell-Regeldiagramm ohne dynamische Ablauf- oder Nachrichtensequenzen. Es stellt die Überlappung der Prüfbereiche (Scopes) für Status-Kombinationen dar: Die Beziehungsattribute/Tags (<code>aggregation Tags</code>, <code>reference Tags</code>) liegen im Schnittbereich der Tabellenprüfungen für Quell- und Zielelemente.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm demonstriert eine unzulässige Statuskombination: Wenn sowohl Quell-/Elternelement (<code>ClassA</code>) als auch Ziel-/Kindelement (<code>ClassB</code>) als <code>obsolete</code> deklariert sind, darf die verbindende Aggregation bzw. Referenz nicht den Status <code>valid</code> tragen. Metamodell-Validierungswerkzeuge müssen sicherstellen, dass Beziehungen zwischen obsoleten Klassen nicht als vollgültig (<code>valid</code>) eingestuft werden.</p>"}, {"id": "FIG-386030d1a2c891f7", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition von ungültigen Statuswert-Kombinationen (Invalid combination of status values) im Rahmen des AUTOSAR Generic Structure Template (M2-Metamodell). Es visualisiert die semantischen Gültigkeitsbereiche für Status-Tags (<code>atp.Status</code>) bei hierarchischen Aggregationen und Referenzen zwischen Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>parent: ClassA</code>: Metaklasse als Aggregationsursprung mit Tag <code>atp.Status = obsolete</code>.\n</li><li><code>child: ClassB</code>: Aggregierte Metaklasse mit Tag <code>atp:Status = obsolete</code>.\n</li><li>Aggregationsbeziehung (<code>aggregation</code>): Komposition von <code>parent: ClassA</code> zu <code>child: ClassB</code> mit Notiz <code>aggregation Tags: atp.Status = valid</code>.\n</li><li><code>source: ClassA</code>: Metaklasse als Referenzursprung mit Tag <code>atp.Status = obsolete</code>.\n</li><li><code>target: ClassB</code>: Referenzierte Metaklasse mit Tag <code>atp.Status = obsolete</code>.\n</li><li>Referenzbeziehung (<code>reference</code>): Gerichtete Assoziation von <code>source: ClassA</code> zu <code>target: ClassB</code> mit Notiz <code>reference Tags: atp.Status = valid</code>.\n</li><li>Blauer gestrichelter Rahmen: Definiert den Gültigkeitsbereich <code>Scope of table status value combinations with parent/source Class</code>, der die Quellklassen (<code>parent: ClassA</code>, <code>source: ClassA</code>) sowie die Beziehungsnotizen umschließt.\n</li><li>Hellblauer (türkiser) gestrichelter Rahmen: Definiert den Gültigkeitsbereich <code>Scope of table status value combinations with child/target Class</code>, der die Zielklassen (<code>child: ClassB</code>, <code>target: ClassB</code>) sowie die Beziehungsnotizen umschließt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell-Regeldiagramm ohne dynamische Ablauf- oder Nachrichtensequenzen. Es stellt die Überlappung der Prüfbereiche (Scopes) für Status-Kombinationen dar: Die Beziehungsattribute/Tags (<code>aggregation Tags</code>, <code>reference Tags</code>) liegen im Schnittbereich der Tabellenprüfungen für Quell- und Zielelemente.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm demonstriert eine unzulässige Statuskombination: Wenn sowohl Quell-/Elternelement (<code>ClassA</code>) als auch Ziel-/Kindelement (<code>ClassB</code>) als <code>obsolete</code> deklariert sind, darf die verbindende Aggregation bzw. Referenz nicht den Status <code>valid</code> tragen. Metamodell-Validierungswerkzeuge müssen sicherstellen, dass Beziehungen zwischen obsoleten Klassen nicht als vollgültig (<code>valid</code>) eingestuft werden.</p>"}, {"id": "FIG-c6c6785dbc09cd43", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition von ungültigen Statuswert-Kombinationen (Invalid combination of status values) im Rahmen des AUTOSAR Generic Structure Template (M2-Metamodell). Es visualisiert die semantischen Gültigkeitsbereiche für Status-Tags (<code>atp.Status</code>) bei hierarchischen Aggregationen und Referenzen zwischen Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>parent: ClassA</code>: Metaklasse als Aggregationsursprung mit Tag <code>atp.Status = obsolete</code>.\n</li><li><code>child: ClassB</code>: Aggregierte Metaklasse mit Tag <code>atp:Status = obsolete</code>.\n</li><li>Aggregationsbeziehung (<code>aggregation</code>): Komposition von <code>parent: ClassA</code> zu <code>child: ClassB</code> mit Notiz <code>aggregation Tags: atp.Status = valid</code>.\n</li><li><code>source: ClassA</code>: Metaklasse als Referenzursprung mit Tag <code>atp.Status = obsolete</code>.\n</li><li><code>target: ClassB</code>: Referenzierte Metaklasse mit Tag <code>atp.Status = obsolete</code>.\n</li><li>Referenzbeziehung (<code>reference</code>): Gerichtete Assoziation von <code>source: ClassA</code> zu <code>target: ClassB</code> mit Notiz <code>reference Tags: atp.Status = valid</code>.\n</li><li>Blauer gestrichelter Rahmen: Definiert den Gültigkeitsbereich <code>Scope of table status value combinations (Aggregation/Reference/Attribute/Enumeration Literal)</code>, der die Quellklassen (<code>parent: ClassA</code>, <code>source: ClassA</code>) sowie die Beziehungsnotizen umschließt.\n</li><li>Hellblauer (türkiser) gestrichelter Rahmen: Definiert den Gültigkeitsbereich <code>Scope of table status value combinations with child/target Class</code>, der die Zielklassen (<code>child: ClassB</code>, <code>target: ClassB</code>) sowie die Beziehungsnotizen umschließt.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodell-Regeldiagramm ohne dynamische Ablauf- oder Nachrichtensequenzen. Es stellt die Überlappung der Prüfbereiche (Scopes) für Status-Kombinationen dar: Die Beziehungsattribute/Tags (<code>aggregation Tags</code>, <code>reference Tags</code>) liegen im Schnittbereich der Tabellenprüfungen für Quell- und Zielelemente.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm demonstriert eine unzulässige Statuskombination: Wenn sowohl Quell-/Elternelement (<code>ClassA</code>) als auch Ziel-/Kindelement (<code>ClassB</code>) als <code>obsolete</code> deklariert sind, darf die verbindende Aggregation bzw. Referenz nicht den Status <code>valid</code> tragen. Metamodell-Validierungswerkzeuge müssen sicherstellen, dass Beziehungen zwischen obsoleten Klassen nicht als vollgültig (<code>valid</code>) eingestuft werden.</p>"}], "trans": [{"from": "FIG-c8dc67bef9ec885b", "to": "FIG-04cb6c1357ca9082", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-04cb6c1357ca9082", "to": "FIG-386030d1a2c891f7", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-386030d1a2c891f7", "to": "FIG-c6c6785dbc09cd43", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Oberer Gültigkeitsbereich (blaue gestrichelte Umrandung): Beschriftung von „Scope of table status value combinations with parent/source Class“ zu „Scope of table status value combinations (Aggregation/Reference/Attribute/Enumeration Literal)“ geändert.\n</li></ul>"}]};
